import numpy as np
from Crypto.Util.number import *

a, b, c, d = [getPrime(256) for _ in range(4)]
point1 = a * d
point2 = b * c
matrix = [[0, a, b], [0, c, d]]

flag = b"vmc{xxxxxxxx}"
flag = bytes_to_long(flag)

def randomArray():
    upper = [[1, 0, 0], [0, 1, 0], [0, 0, 1]]
    low = [[1, 0, 0], [0, 1, 0], [0, 0, 1]]
    for i in range(3):
        for j in range(i + 1, 3):
            upper[i][j] = getPrime(256)
            low[j][i] = getPrime(256)
    result = np.array(upper) @ np.array(low)
    return result

A = np.array([[flag, 0, 0]] + matrix)
B = randomArray()
C = randomArray()
MAT = C @ A @ B


print(point1)
print(point2)
print(MAT)

